import{_ as r,c as o,a2 as a,o as l}from"./chunks/framework.DPuwY6B9.js";const e="/assets/product-stock-multipliers.Dqlv0-a6.png",u="/assets/product-stock-multipliers@2x.BMmtOvNy.png",i="/assets/attribute-stock-multipliers.CCCh7PcV.png",c="/assets/attribute-stock-multipliers@2x.B9LbuuQY.png",s="/assets/attribute-term-multipliers.CRZBB3Rb.png",p="/assets/attribute-term-multipliers@2x.BbJpb7n-.png",_=JSON.parse('{"title":"Stock Multipliers","description":"","frontmatter":{},"headers":[],"relativePath":"stock-multipliers.md","filePath":"stock-multipliers.md"}'),m={name:"stock-multipliers.md"},n=e+", "+u+" 2x",d=i+", "+c+" 2x",h=s+", "+p+" 2x";function b(k,t,f,g,y,v){return l(),o("div",null,t[0]||(t[0]=[a('<h1 id="stock-multipliers" tabindex="-1">Stock Multipliers <a class="header-anchor" href="#stock-multipliers" aria-label="Permalink to &quot;Stock Multipliers&quot;">​</a></h1><p>Stock multipliers are an essential feature for stock setups that require variable quantities. In simple terms, stock multipliers allow you to specify a decimal number to tell your site how many of a particular stock to use for a product, variation, attribute term, or attribute stock item.</p><h2 id="product-multipliers" tabindex="-1">Product multipliers <a class="header-anchor" href="#product-multipliers" aria-label="Permalink to &quot;Product multipliers&quot;">​</a></h2><p><img src="'+e+'" alt="Product stock multipliers" srcset="'+n+'" width="1300" height="708"></p><p>Stock multipliers on products and product variations allow you to specify a multiplier to use for <a href="./terminology#product-stock">product stock</a> (if stock management is enabled), or for associated <a href="./terminology#attribute-stock">attribute stock</a> (if stock management is disabled).</p><p>This is particularly useful for variable products where stock is enabled at the product level and different multipliers are set for each of its variations. An example of this is a product using weight-based stock, where the total weight is entered as product-level stock, and each variation has options such as <code>500g</code>, <code>1kg</code>, etc. When a variation is purchased, the respective amount of stock will be deducted from the total product stock.</p><p>This becomes even more powerful when combined with <a href="#term-multipliers">term multipliers</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Since product multipliers work directly with product stock, you&#39;re not required to use attribute stock items. This also means you can use product multipliers with <a href="./terminology#custom-attributes">custom attributes</a> if you want to.</p></div><h2 id="attribute-stock-multipliers" tabindex="-1">Attribute stock multipliers <a class="header-anchor" href="#attribute-stock-multipliers" aria-label="Permalink to &quot;Attribute stock multipliers&quot;">​</a></h2><p><img src="'+i+'" alt="Attribute stock multipliers" srcset="'+d+'" width="1166" height="308"></p><p>Stock multipliers can be set for individual match rules of an <a href="./terminology#attribute-stock-item">attribute stock item</a>. A stock multiplier of <code>0</code> can be set to force out of stock, or <code>-1</code> to prevent matching.</p><p>Product multipliers on matching products (with stock management is disabled) will take priority over attribute stock multipliers. This can be disabled per stock item with the <code>Lock multipliers</code> settings.</p><p>Attribute stock items will also inherit <a href="#term-multipliers">term multipliers</a>.</p><h2 id="term-multipliers" tabindex="-1">Term multipliers <a class="header-anchor" href="#term-multipliers" aria-label="Permalink to &quot;Term multipliers&quot;">​</a></h2><p><img src="'+s+'" alt="Attribute term multipliers" srcset="'+h+'" width="1300" height="500"></p><p>Term multipliers allow you to specify default stock multipliers directly on <a href="./terminology#attribute-term">attribute terms</a>.</p><p>These multiplier values will be used for all products and attribute stock items using these terms, so long as a stock multiplier has not been explicitly set on the respective product/variation or attribute stock match rule.</p><p>Term multipliers make it easy to manage stock multipliers across your site by setting multiplier values once and having them apply to all associated products and attribute stock.</p><p>This can be particularly powerful when used with <a href="./terminology#any-variation">&quot;any&quot; variations</a> or attribute stock <a href="./terminology#match-rule">match rules</a> with multiple terms, as the appropriate multiplier will be used automatically without the need for separate product variations or match rules for each multiplier value.</p><div class="danger custom-block"><p class="custom-block-title">WARNING</p><p>When a product or attribute stock item has multiple <strong>attributes</strong> containing term multipliers, the behavior is <em><strong>non-deterministic</strong></em>. Only one multiplier can be used at a time, and <em>any one</em> of the matching multiplier values could be used.</p></div><div class="warning custom-block"><p class="custom-block-title">TAKE NOTE</p><p>Term multipliers can only be set on global <a href="./terminology#attribute">attributes</a>. It&#39;s not possible to set term multipliers for <a href="./terminology#custom-attributes">custom attributes</a>.</p></div>',21)]))}const x=r(m,[["render",b]]);export{_ as __pageData,x as default};
